// One item per PDF attachment, in the same shape as a test file.
// Other attachments are skipped. An email without a PDF produces no item.
const out = [];
for (const item of $input.all()) {
  const m = item.json;
  const from = (m.from && m.from.value && m.from.value[0]) || {};
  for (const [key, bin] of Object.entries(item.binary || {})) {
    const name = bin.fileName || key;
    const isPdf = bin.mimeType === 'application/pdf' || /\.pdf$/i.test(name);
    if (!isPdf) continue;
    out.push({
      json: {
        source: 'gmail',
        run_id: null,
        case_id: null,
        file_id: null,
        file_name: name,
        email_id: m.id || null,
        thread_id: m.threadId || null,
        sender: from.address || (m.from && m.from.text) || '',
        sender_name: from.name || '',
        subject: m.subject || '',
        received_at: m.date ? new Date(m.date).toISOString() : new Date().toISOString(),
        prior_dup_keys: [],
      },
      binary: { data: bin },
    });
  }
}
return out;

// Settings for every invoice (Project 3 design doc, sections 3, 3b and 4).
// The eval run records MODEL and PROMPT_VERSION, so change them only on purpose.
const MODEL = 'gemini-3.5-flash-lite';
const PROMPT_VERSION = 'p3-prompt-v2'; // v2 (28 Oct): rule 8, supplier's full name (R1: T04, T09)
const MAX_OUTPUT_TOKENS = 8192;

// Checks done by code after the AI has read the invoice (stage 4).
const HOME_CURRENCY = 'USD';
const MONEY_TOLERANCE = 0.01; // differences up to 1 cent are rounding, not an error
const TIMEZONE = 'America/Denver'; // "today" for the future-date check

const CATEGORIES = [
  { code: 'coffee_tea', name: 'Coffee & Tea', definition: 'Roasted coffee beans, ground coffee, cold brew packs and tea.' },
  { code: 'dairy', name: 'Dairy & Milk Alternatives', definition: 'Milk, cream, half and half, and plant-based milks such as oat, almond or soy.' },
  { code: 'food', name: 'Food & Bakery', definition: 'Food sold to customers or used to make it: pastries, baked goods, sandwiches, food ingredients. Never the bags or boxes food goes in.' },
  { code: 'packaging', name: 'To-Go Packaging & Disposables', definition: 'Anything handed to a customer with an order: cups, lids, sleeves, straws, stirrers, napkins, carriers, bags and food containers.' },
  { code: 'supplies', name: 'Kitchen & Cleaning Supplies', definition: 'Items staff use up that customers never take: gloves, paper towels, food-safety labels, cleaning chemicals, trash bags.' },
  { code: 'cleaning_services', name: 'Cleaning & Maintenance Services', definition: 'Work billed by a service company: janitorial visits, hood and grease trap cleaning, floor care, window and carpet cleaning.' },
  { code: 'freight', name: 'Freight & Delivery Fees', definition: 'Delivery, freight or shipping charges on any invoice.' },
];

// Stores and the words that identify them in a delivery address or a line description.
// "shared" = a line for several stores; reports split it equally.
const BRANCHES = [
  { code: 'larimer', name: 'Larimer St', keywords: ['larimer'] },
  { code: 'highlands', name: 'Highlands', keywords: ['highlands', '32nd ave'] },
  { code: 'washpark', name: 'Wash Park', keywords: ['wash park', 'gaylord'] },
  { code: 'shared', name: 'Shared', keywords: [] },
];
const SHARED_PHRASES = ['all 3 stores', 'all three stores', 'all stores', 'all locations'];

// QuickBooks Online (stage 6b): sandbox company, IDs from design doc section 5b.
// Vendors are matched by name at run time and never created by the workflow.
const QUICKBOOKS = {
  base_url: 'https://sandbox-quickbooks.api.intuit.com/v3/company/YOUR_QUICKBOOKS_COMPANY_ID',
  minor_version: '75',
  accounts: { // cost category -> expense account
    coffee_tea: '1150040000', dairy: '1150040001', food: '1150040002', packaging: '1150040003',
    cleaning_services: '1150040004', supplies: '1150040005', freight: '1150040006',
  },
  tax_account: '1150040007', // Sales Tax Paid
  classes: { larimer: '741030', highlands: '741031', washpark: '741032', shared: '741033' }, // store -> Class
  doc_number_max: 21, // QuickBooks limit for the bill number
};

const SYSTEM_PROMPT = [
  'You read one supplier document for the accounts payable team of Copper Kettle Café',
  'and copy what is printed into JSON. You never calculate, correct or complete',
  'anything: code checks the numbers after you.',
  '',
  '1. is_invoice is true only for a bill that asks Copper Kettle to pay for goods or',
  '   services (it shows an amount due). A copy or reminder that contains the invoice',
  '   itself counts. Price lists, menus, quotes and brochures are false. If false, set',
  '   every other field to null and line_items to [].',
  '2. Copy exactly what is printed. If the numbers on the document do not agree with',
  '   each other, still copy them as printed. Never fix a subtotal, tax, total or',
  '   line amount.',
  '3. Use null for anything that is not printed. Do not guess. PO numbers, account',
  '   numbers and customer numbers are not invoice numbers: if the invoice number',
  '   field is empty, invoice_number is null.',
  '4. Dates as YYYY-MM-DD. US suppliers write the month first: 10/04/2026 is 2026-10-04.',
  '5. Amounts as plain numbers, without currency symbols or thousands separators.',
  '   A tax printed as 0.00 is 0, not null. currency is the 3-letter code.',
  '6. Every row of the item table is one line item, including freight and delivery',
  '   fees, in the printed order. Read every page. Subtotal, tax and total rows are',
  '   not line items.',
  '7. ship_to is the delivery address block only (labelled Ship to, Deliver to or',
  '   similar), copied on one line. Bill to, Sold to and Client blocks are the head',
  '   office billing address, not a delivery address. No delivery block: null.',
  '8. supplier_name is the supplier\'s full business name. If the logo shows only a short',
  '   name and the full name is printed elsewhere (for example after "payable to" or in',
  '   the footer), copy that full name.',
  '9. category: pick one code per line from the list below, using its definition.',
  '   If none fits, use null. Never invent a new code.',
  '',
  'Categories:',
  ...CATEGORIES.map(c => '- ' + c.code + ' (' + c.name + '): ' + c.definition),
].join('\n');

return $input.all().map(item => ({
  json: {
    ...item.json,
    config: {
      model: MODEL,
      prompt_version: PROMPT_VERSION,
      max_output_tokens: MAX_OUTPUT_TOKENS,
      home_currency: HOME_CURRENCY,
      money_tolerance: MONEY_TOLERANCE,
      timezone: TIMEZONE,
      categories: CATEGORIES,
      branches: BRANCHES,
      shared_phrases: SHARED_PHRASES,
      quickbooks: QUICKBOOKS,
      system_prompt: SYSTEM_PROMPT,
    },
  },
  binary: item.binary,
}));

// Requests from the Eval Runner (or the dev door), cleaned up before the download.
// prior_dup_keys = earlier documents of the same eval run (for the duplicate check);
// accepted as a list or as JSON text.
const list = (v) => {
  if (Array.isArray(v)) return v;
  if (typeof v === 'string' && v.trim()) {
    try { const p = JSON.parse(v); return Array.isArray(p) ? p : []; } catch (e) { return []; }
  }
  return [];
};
return $input.all().map(i => {
  const r = i.json;
  return { json: {
    source: r.source || 'eval',
    run_id: r.run_id ? String(r.run_id) : null,
    case_id: r.case_id ? String(r.case_id) : null,
    file_id: String(r.file_id || ''),
    file_name: String(r.file_name || ''),
    prior_dup_keys: list(r.prior_dup_keys),
  } };
});

// Build-time check only: a text PDF, a scan and the brochure.
// Disable this door once the Eval Runner exists.
const DEV_FILES = { 'HB-10482.pdf': 'T01', 'Scan_2026-10-09_0842.pdf': 'T06', 'BrightClean_Service_Menu_2027.pdf': 'T05' };
const run = 'dev-' + $now.toFormat('yyyyLLdd-HHmm');
return $input.all()
  .filter(i => DEV_FILES[i.json.name])
  .map(i => ({ json: { source: 'dev', run_id: run, case_id: DEV_FILES[i.json.name], file_id: i.json.id, file_name: i.json.name, prior_dup_keys: [] } }));

// Same item shape as an email attachment, so everything after this point
// runs exactly the same code for test files and real emails.
const requests = $('Test File Request').all();
return $input.all().map((item, i) => ({
  json: {
    ...requests[i].json,
    email_id: null,
    thread_id: null,
    sender: '',
    sender_name: '',
    subject: '',
    received_at: new Date().toISOString(),
  },
  binary: { data: item.binary.data },
}));

// Turns the PDF into base64 for Gemini and checks that it really is a PDF.
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  out.push({
    json: {
      ...items[i].json,
      pdf_bytes: buf.length,
      pdf_header_ok: buf.subarray(0, 5).toString('latin1') === '%PDF-',
      pdf_base64: buf.toString('base64'),
    },
    binary: items[i].binary,
  });
}
return out;

// Marks each PDF as text_layer or image_only (scan or photo), for the log and the eval.
// Gemini reads the PDF itself either way; the extracted text is not sent to the AI.
// Also builds the Gemini request: system prompt, the PDF, and the locked JSON schema.
const prepared = $('Prepare PDF').all();
const out = [];
$input.all().forEach((it, i) => {
  const src = prepared[i].json;
  const cfg = src.config;
  const text = String(it.json.text || '');
  const chars = text.replace(/\s+/g, '').length;
  const readPath = it.json.error ? 'extract_failed' : (chars >= 50 ? 'text_layer' : 'image_only');

  const nStr = (description) => (description ? { type: 'STRING', nullable: true, description } : { type: 'STRING', nullable: true });
  const nNum = { type: 'NUMBER', nullable: true };
  const lineProps = ['description', 'quantity', 'unit_price', 'amount', 'category'];
  const topProps = ['is_invoice', 'invoice_number', 'supplier_name', 'invoice_date', 'due_date', 'currency',
    'subtotal', 'tax', 'total', 'ship_to', 'line_items'];
  const schema = {
    type: 'OBJECT',
    properties: {
      is_invoice: { type: 'BOOLEAN' },
      invoice_number: nStr(),
      supplier_name: nStr(),
      invoice_date: nStr('YYYY-MM-DD'),
      due_date: nStr('YYYY-MM-DD'),
      currency: nStr('3-letter code, for example USD'),
      subtotal: nNum,
      tax: nNum,
      total: nNum,
      ship_to: nStr('Delivery address as printed, on one line'),
      line_items: {
        type: 'ARRAY',
        items: {
          type: 'OBJECT',
          properties: {
            description: { type: 'STRING' },
            quantity: nNum,
            unit_price: nNum,
            amount: nNum,
            category: { type: 'STRING', nullable: true, enum: cfg.categories.map(c => c.code) },
          },
          required: lineProps,
          propertyOrdering: lineProps,
        },
      },
    },
    required: topProps,
    propertyOrdering: topProps,
  };

  const request = {
    systemInstruction: { parts: [{ text: cfg.system_prompt }] },
    contents: [{ role: 'user', parts: [
      { inlineData: { mimeType: 'application/pdf', data: src.pdf_base64 } },
      { text: 'Read this document.' },
    ] }],
    generationConfig: {
      temperature: 0,
      maxOutputTokens: cfg.max_output_tokens,
      responseMimeType: 'application/json',
      responseSchema: schema,
    },
  };

  const { pdf_base64, ...rest } = src;
  out.push({
    json: {
      ...rest,
      read_path: readPath,
      text_chars: chars,
      pages: it.json.numpages ?? null,
      read_started_at: Date.now(),
      gemini_request: request,
    },
    binary: prepared[i].binary,
  });
});
return out;

// Turns Gemini's reply into the raw reading. No checks on the numbers yet: stage 4 does that.
// If Gemini still failed after 3 attempts, the item carries on marked ai_failed,
// so it is logged and reported instead of disappearing.
const ctx = $('Read Path').item.json;
const r = $json;
const usage = r.usageMetadata || {};
let reading = null;
let aiError = null;
let finishReason = null;

if (r.error) {
  const e = r.error;
  const msg = (e && (e.message || e.description)) || (typeof e === 'string' ? e : 'unknown error');
  aiError = ('Gemini request failed: ' + msg).slice(0, 500);
} else {
  const cand = (r.candidates || [])[0] || {};
  finishReason = cand.finishReason || null;
  const text = ((cand.content && cand.content.parts) || []).map(p => p.text || '').join('');
  if (!text) {
    aiError = 'Gemini returned no text (' + (cand.finishReason || (r.promptFeedback && r.promptFeedback.blockReason) || 'no reason given') + ')';
  } else {
    try { reading = JSON.parse(text); }
    catch (e) { aiError = 'Gemini reply was not valid JSON (finishReason ' + (cand.finishReason || 'unknown') + ')'; }
  }
  if (reading !== null && (typeof reading !== 'object' || Array.isArray(reading))) {
    reading = null;
    aiError = 'Gemini reply was JSON but not an object';
  }
}

const { gemini_request, ...rest } = ctx;
return {
  json: {
    ...rest,
    reading,
    ai_failed: !reading,
    ai_error: aiError,
    finish_reason: finishReason,
    model_version: r.modelVersion || ctx.config.model,
    tokens_in: usage.promptTokenCount ?? null,
    tokens_out: usage.candidatesTokenCount ?? null,
    tokens_thinking: usage.thoughtsTokenCount ?? null,
    read_ms: Date.now() - ctx.read_started_at,
  },
  binary: $('Read Path').item.binary,
};

// Stage 4: code checks what the AI read, then decides the store (branch) of every line.
// The AI only copied what is printed. Every number is recalculated here, and every problem
// becomes a reason code (design doc, section 4). Any reason sends the invoice to review.
// Duplicates are decided in stage 5 (Decide Route), with the dup_key built here.

// ---- allocate.js (criteria p3-v2): branch by rule, category checked against the list ----
function branchesIn(text, cfg) {
  const t = String(text || '').toLowerCase();
  return Object.entries(cfg.branches)
    .filter(([, b]) => b.keywords.some((k) => t.includes(k)))
    .map(([code]) => code);
}
function defaultBranch(shipTo, cfg) {
  const found = branchesIn(shipTo, cfg);
  return found.length === 1 ? found[0] : null;
}
function lineBranch(description, fallback, cfg) {
  const t = String(description || '').toLowerCase();
  if (cfg.sharedPhrases.some((p) => t.includes(p))) return 'shared';
  const found = branchesIn(t, cfg);
  if (found.length > 1) return 'shared';
  if (found.length === 1) return found[0];
  return fallback || 'unassigned';
}
function allocate(invoice, cfg) {
  const shipToBranch = defaultBranch(invoice.ship_to, cfg);
  const lines = (invoice.line_items || []).map((li) => {
    const category = li.category ?? null;
    return {
      branch: lineBranch(li.description, shipToBranch, cfg),
      category,
      category_ok: category !== null && cfg.categories.includes(category),
    };
  });
  const reasons = [];
  if (lines.some((l) => l.branch === 'unassigned')) reasons.push('branch_unknown');
  if (lines.some((l) => !l.category_ok)) reasons.push('uncategorized_line');
  return { ship_to_branch: shipToBranch, lines, reasons };
}

// ---- reading the AI output safely ----
const text = (v) => { const s = String(v ?? '').trim(); return s ? s : null; };
const num = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = typeof v === 'number' ? v : Number(String(v).replace(/[$,\s]/g, ''));
  return Number.isFinite(n) ? n : null;
};
const isoDate = (v) => { // a real calendar date written YYYY-MM-DD, otherwise null
  const s = String(v ?? '').trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return null;
  const d = new Date(s + 'T00:00:00Z');
  return !isNaN(d) && d.toISOString().slice(0, 10) === s ? s : null;
};
const cents = (n) => Math.round(n * 100) / 100;
const differs = (a, b, tol) => Math.abs(a - b) > tol + 1e-9;

// ---- duplicate key: same supplier + same invoice number, written loosely ----
const SUFFIXES = ['llc', 'inc', 'co', 'company', 'corp', 'ltd'];
const normSupplier = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase()
  .replace(/['\u2019]/g, '').replace(/[^a-z0-9]+/g, ' ').trim().split(' ')
  .filter((w) => w && !SUFFIXES.includes(w)).join(' ');
const normNumber = (s) => String(s || '').toUpperCase().replace(/[\s#]/g, '');

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const cfg = j.config;
  const tol = cfg.money_tolerance;
  const allocCfg = {
    branches: Object.fromEntries(cfg.branches.filter((b) => b.keywords.length).map((b) => [b.code, { name: b.name, keywords: b.keywords }])),
    sharedPhrases: cfg.shared_phrases,
    categories: cfg.categories.map((c) => c.code),
  };
  const base = { ...j, check_status: null, invoice: null, allocation: null, dup_key: null, reasons: [], details: {} };

  // AI failed: nothing to check. Stage 7 logs it and tells the team.
  if (j.ai_failed || !j.reading) {
    out.push({ json: { ...base, check_status: 'error', error_step: 'read', error_message: j.ai_error || 'No reading' }, binary: item.binary });
    continue;
  }
  const r = j.reading;
  if (r.is_invoice !== true) {
    out.push({ json: { ...base, check_status: 'not_invoice' }, binary: item.binary });
    continue;
  }

  // What the AI read, cleaned up (types only, never corrected).
  const inv = {
    invoice_number: text(r.invoice_number),
    supplier: text(r.supplier_name),
    invoice_date: isoDate(r.invoice_date),
    due_date: isoDate(r.due_date),
    currency: text(r.currency) ? text(r.currency).toUpperCase() : null,
    subtotal: num(r.subtotal),
    tax: num(r.tax),
    total: num(r.total),
    ship_to: text(r.ship_to),
    line_items: (Array.isArray(r.line_items) ? r.line_items : []).map((li, n) => ({
      line_no: n + 1,
      description: text(li && li.description) || '',
      quantity: num(li && li.quantity),
      unit_price: num(li && li.unit_price),
      amount: num(li && li.amount),
      category: text(li && li.category),
    })),
  };
  const lines = inv.line_items;
  const reasons = [];
  const details = {};
  const flag = (code, info) => { reasons.push(code); if (info) details[code] = info; };

  // Required fields
  if (!inv.invoice_number) flag('missing_invoice_number', { field: 'invoice number' });
  if (!inv.supplier) flag('missing_supplier', { field: 'supplier name' });
  if (!inv.invoice_date) flag('missing_invoice_date', { field: 'invoice date', printed: r.invoice_date ?? null });
  if (inv.total === null) flag('missing_total', { field: 'total' });
  if (!lines.length) flag('missing_line_items', { field: 'line items' });

  // Each line: quantity x unit price = amount (a missing amount also needs a person)
  const badLines = lines.filter((l) => l.amount === null
    || (l.quantity !== null && l.unit_price !== null && differs(l.quantity * l.unit_price, l.amount, tol)))
    .map((l) => ({ line_no: l.line_no, description: l.description, quantity: l.quantity, unit_price: l.unit_price,
      expected: l.quantity !== null && l.unit_price !== null ? cents(l.quantity * l.unit_price) : null, printed: l.amount }));
  if (badLines.length) flag('line_math_mismatch', { lines: badLines });

  // Lines add up to the subtotal; subtotal + tax = total
  const linesTotal = cents(lines.reduce((s, l) => s + (l.amount ?? 0), 0));
  if (lines.length && inv.subtotal !== null && differs(linesTotal, inv.subtotal, tol)) {
    flag('sum_mismatch', { lines_total: linesTotal, subtotal: inv.subtotal, difference: cents(Math.abs(linesTotal - inv.subtotal)) });
  }
  const before = inv.subtotal !== null ? inv.subtotal : (lines.length ? linesTotal : null);
  if (inv.total !== null && before !== null && differs(before + (inv.tax ?? 0), inv.total, tol)) {
    flag('total_mismatch', { subtotal: before, tax: inv.tax ?? 0, expected: cents(before + (inv.tax ?? 0)), printed: inv.total });
  }

  // Dates and currency
  const today = $now.setZone(cfg.timezone).toISODate();
  if (inv.invoice_date && inv.due_date && inv.due_date < inv.invoice_date) {
    flag('due_before_invoice', { due_date: inv.due_date, invoice_date: inv.invoice_date });
  }
  if (inv.invoice_date && inv.invoice_date > today) flag('future_date', { invoice_date: inv.invoice_date, today });
  if (inv.currency && inv.currency !== cfg.home_currency) flag('currency_not_usd', { currency: inv.currency });

  // Branch per line (rule) and category check (AI chose, code checks)
  const alloc = allocate(inv, allocCfg);
  if (alloc.reasons.includes('branch_unknown')) {
    const un = lines.filter((l, n) => alloc.lines[n].branch === 'unassigned');
    flag('branch_unknown', { lines: un.length, amount: cents(un.reduce((s, l) => s + (l.amount ?? 0), 0)) });
  }
  if (alloc.reasons.includes('uncategorized_line')) {
    const un = lines.filter((l, n) => !alloc.lines[n].category_ok);
    flag('uncategorized_line', { lines: un.length, amount: cents(un.reduce((s, l) => s + (l.amount ?? 0), 0)),
      examples: un.slice(0, 3).map((l) => l.description) });
  }

  const dupKey = inv.supplier && inv.invoice_number ? normSupplier(inv.supplier) + '|' + normNumber(inv.invoice_number) : null;
  out.push({
    json: {
      ...base,
      check_status: 'invoice',
      invoice: { ...inv, lines_total: linesTotal },
      allocation: { ship_to_branch: alloc.ship_to_branch, lines: alloc.lines.map(({ branch, category }) => ({ branch, category })) },
      dup_key: dupKey,
      reasons,
      details,
    },
    binary: item.binary,
  });
}

// One Airtable search per email finds earlier invoices for all its PDFs (stage 5, email only).
const keys = [...new Set(out.map((o) => o.json.dup_key).filter(Boolean))];
const formula = keys.length
  ? 'OR(' + keys.map((k) => '{Dup key}="' + k.replace(/["\\]/g, '\\$&') + '"').join(',') + ')'
  : 'FALSE()';
for (const o of out) o.json.dup_lookup_formula = formula;
return out;

// Stage 5: one final route per document: error, not_invoice, duplicate, needs_review or recorded.
// Earlier invoices to compare with:
// - real email: records found in Airtable by "Find Earlier Invoices" (any status)
// - test file: the earlier documents of the same eval run, sent by the Eval Runner
// Same supplier + same number + same total = duplicate (nothing is recorded again).
// Same supplier + same number but a different total = needs_review (maybe a corrected invoice).
const items = $('Check & Allocate').all();
const isTest = items[0].json.source !== 'gmail';
const tolOf = (j) => (j.config && j.config.money_tolerance) || 0.01;
const toNum = (v) => (v === null || v === undefined || v === '' || !Number.isFinite(Number(v)) ? null : Number(v));

let known = [];
if (isTest) {
  const prior = items[0].json.prior_dup_keys;
  known = (Array.isArray(prior) ? prior : [])
    .filter((p) => p && p.dup_key)
    .map((p) => ({ dup_key: String(p.dup_key), total: toNum(p.total), ref: p.case_id ? String(p.case_id) : 'earlier test file', recorded_at: null, where: 'this eval run' }));
} else {
  known = $input.all().map((i) => i.json).filter((r) => r && typeof r.id === 'string' && r.id.startsWith('rec'))
    .map((r) => {
      const f = r.fields || r;
      return { dup_key: String(f['Dup key'] || ''), total: toNum(f['Total']), ref: r.id, label: f['Invoice'] || null,
        recorded_at: f['Received at'] || null, status: f['Status'] || null, where: 'airtable' };
    })
    .filter((k) => k.dup_key);
}

const earlierFound = known.length;
const out = [];
items.forEach((item) => {
  const j = item.json;
  const reasons = [...(j.reasons || [])];
  const details = { ...(j.details || {}) };
  let route;
  let duplicateOf = null;

  if (j.check_status === 'error') route = 'error';
  else if (j.check_status === 'not_invoice') route = 'not_invoice';
  else {
    const match = j.dup_key ? known.find((k) => k.dup_key === j.dup_key) : null;
    const total = j.invoice ? j.invoice.total : null;
    if (match && total !== null && match.total !== null && Math.abs(total - match.total) <= tolOf(j) + 1e-9) {
      route = 'duplicate';
      duplicateOf = match;
    } else {
      if (match) {
        reasons.push('duplicate_amount_differs');
        details.duplicate_amount_differs = { earlier: match, earlier_total: match.total, this_total: total };
      }
      route = reasons.length ? 'needs_review' : 'recorded';
    }
    // Two copies in the same email or batch: the second one is compared with the first.
    if ((route === 'recorded' || route === 'needs_review') && j.dup_key) {
      known.push({ dup_key: j.dup_key, total, ref: j.case_id || j.file_name, recorded_at: null, where: 'this execution' });
    }
  }

  out.push({
    json: { ...j, route, reasons, details, duplicate_of: duplicateOf, earlier_found: earlierFound },
    binary: item.binary,
  });
});
return out;

// Test files stop here: no Drive, Airtable, QuickBooks or Slack.
// This item goes back to the Eval Runner, which checks it against the answer key.
// dup_key and total let the runner pass this document on as an "earlier invoice"
// to the next cases of the same run (only if it would have been recorded).
return $input.all().map((item) => {
  const j = item.json;
  return {
    json: {
      case_id: j.case_id,
      run_id: j.run_id,
      source: j.source,
      file_name: j.file_name,
      route: j.route,
      reasons: j.reasons,
      duplicate_of: j.duplicate_of ? j.duplicate_of.ref : null,
      dup_key: j.dup_key,
      total: j.invoice ? j.invoice.total : null,
      is_invoice: j.reading ? j.reading.is_invoice === true : null,
      reading: j.reading,
      allocation: j.allocation,
      read_path: j.read_path,
      text_chars: j.text_chars,
      pages: j.pages,
      ai_failed: j.ai_failed === true,
      ai_error: j.ai_error || null,
      model: j.config.model,
      prompt_version: j.config.prompt_version,
      model_version: j.model_version,
      tokens_in: j.tokens_in,
      tokens_out: j.tokens_out,
      read_ms: j.read_ms,
      execution_id: String($execution.id),
    },
  };
});

// Stage 6a: everything needed to record one invoice (routes recorded and needs_review).
// - the PDF file name for Drive: <supplier>_<invoice number>.pdf
// - the Airtable Invoices fields and the Line Items fields (written exactly, typecast on)
// - the problem statement for a person: what is wrong, why it was flagged and what to check,
//   one per reason, written by code from the reason codes (the same text goes to Slack in stage 7a)
const money = (n) => (n === null || n === undefined ? 'unknown' : '$' + Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }));
const day = (d) => {
  if (!d) return 'an unknown date';
  const dt = DateTime.fromISO(String(d).slice(0, 10));
  return dt.isValid ? dt.toFormat('LLL d, yyyy') : String(d);
};
const SUFFIXES = ['llc', 'inc', 'co', 'company', 'corp', 'ltd'];
const cleanName = (s) => {
  const words = String(s || '').replace(/[\\/:*?"<>|]/g, ' ').replace(/[.,]/g, ' ').split(/\s+/).filter(Boolean);
  while (words.length > 1 && SUFFIXES.includes(words[words.length - 1].toLowerCase())) words.pop();
  return words.join(' ');
};
const short = (t, n = 40) => (String(t).length > n ? String(t).slice(0, n - 1) + '…' : String(t));

// Why it was flagged, one sentence per kind of reason.
const MATH_WHY = 'Invoices are only recorded when the lines, tax and total agree.';
const DATE_WHY = 'A wrong date can make a payment late or early.';
const MISSING_WHY = 'Required fields must be readable before an invoice is recorded.';
const ALLOCATION_WHY = 'Every line needs a store and a cost category for the store reports.';
const WHY = {
  sum_mismatch: MATH_WHY, line_math_mismatch: MATH_WHY, total_mismatch: MATH_WHY,
  due_before_invoice: DATE_WHY, future_date: DATE_WHY,
  missing_invoice_number: MISSING_WHY, missing_supplier: MISSING_WHY, missing_invoice_date: MISSING_WHY,
  missing_total: MISSING_WHY, missing_line_items: MISSING_WHY,
  currency_not_usd: 'The books are kept in USD.',
  duplicate_amount_differs: 'Paying both copies would pay this invoice twice.',
  branch_unknown: ALLOCATION_WHY, uncategorized_line: ALLOCATION_WHY,
  vendor_not_in_quickbooks: 'Bills are only created for vendors that already exist in QuickBooks, so no duplicate vendors are made.',
};

const MATH_CHECK = 'Open the PDF. If it shows the same numbers, the supplier\'s invoice is wrong: ask them for a corrected one. If it doesn\'t, the reading was wrong: fix the record in Airtable.';
function problemsFor(j) {
  const inv = j.invoice || {};
  const d = j.details || {};
  const out = [];
  for (const code of j.reasons || []) {
    const x = d[code] || {};
    let problem;
    let check;
    switch (code) {
      case 'sum_mismatch':
        problem = `The line items add up to ${money(x.lines_total)}, but the invoice states a subtotal of ${money(x.subtotal)} (${money(x.difference)} difference).`;
        check = MATH_CHECK; break;
      case 'line_math_mismatch': {
        const lines = (x.lines || []).slice(0, 3).map((l) => (l.printed === null
          ? `Line ${l.line_no} (${short(l.description)}): the amount could not be read.`
          : `Line ${l.line_no} (${short(l.description)}): ${l.quantity} × ${money(l.unit_price)} = ${money(l.expected)}, but the invoice shows ${money(l.printed)}.`));
        const more = (x.lines || []).length - lines.length;
        problem = lines.join(' ') + (more > 0 ? ` And ${more} more line(s).` : '');
        check = MATH_CHECK; break;
      }
      case 'total_mismatch':
        problem = `Subtotal ${money(x.subtotal)} + tax ${money(x.tax)} = ${money(x.expected)}, but the invoice total is ${money(x.printed)}.`;
        check = MATH_CHECK; break;
      case 'due_before_invoice':
        problem = `The due date (${day(x.due_date)}) is before the invoice date (${day(x.invoice_date)}).`;
        check = 'Probably a typo. Confirm the real due date with the supplier before scheduling payment.'; break;
      case 'missing_invoice_number':
        problem = 'No invoice number was found, so the system can\'t check whether it was already paid.';
        check = 'Open the PDF. If a number is there, add it in Airtable. If there\'s none, ask the supplier for one. PO and account numbers are not invoice numbers.'; break;
      case 'missing_supplier':
      case 'missing_invoice_date':
      case 'missing_total':
      case 'missing_line_items':
        problem = `The ${x.field || code.replace('missing_', '').replace(/_/g, ' ')} could not be read.`;
        check = 'Open the PDF and fill it in in Airtable.'; break;
      case 'future_date':
        problem = `The invoice date (${day(x.invoice_date)}) is in the future.`;
        check = 'Check the date on the PDF before scheduling payment.'; break;
      case 'currency_not_usd':
        problem = `This invoice is in ${x.currency}, not USD.`;
        check = 'Confirm the USD amount with the supplier before paying.'; break;
      case 'duplicate_amount_differs': {
        const e = x.earlier || {};
        problem = `${inv.supplier || 'This supplier'} ${inv.invoice_number || ''} was already recorded${e.recorded_at ? ' on ' + day(e.recorded_at) : ''} for ${money(x.earlier_total)}, but this copy says ${money(x.this_total)}.`;
        check = 'It may be a corrected invoice. Keep one and void the other.'; break;
      }
      case 'branch_unknown':
        problem = `${x.lines} line(s) totalling ${money(x.amount)} could not be assigned to a store: no delivery address and no store named on the line.`;
        check = 'Set the Branch on those lines in Airtable. If the supplier always leaves the address off, ask them to add it.'; break;
      case 'vendor_not_in_quickbooks': {
        const who = x.supplier || inv.supplier || 'The supplier';
        if ((x.matches || []).length > 1) {
          problem = `${who} matches more than one vendor in QuickBooks (${x.matches.join(', ')}), so no bill was created.`;
          check = 'Merge or rename those vendors in QuickBooks so only one matches, then create the bill from the Airtable record.';
        } else {
          problem = `${who} is not set up as a vendor in QuickBooks, so no bill was created.`;
          check = 'Add the vendor in QuickBooks (or fix the spelling), then create the bill from the Airtable record.';
        }
        break;
      }
      case 'uncategorized_line':
        problem = `${x.lines} line(s) totalling ${money(x.amount)} have no cost category` + ((x.examples || []).length ? ` (e.g. "${short(x.examples[0])}").` : '.');
        check = 'Pick the Category in Airtable. If it is a new kind of purchase, add it to the category list.'; break;
      default:
        problem = `Flagged: ${code}.`;
        check = 'Open the PDF and check the record in Airtable.';
    }
    out.push({ reason: code, problem, why: WHY[code] || 'A person needs to look at this before it is recorded.', check });
  }
  return out;
}

return $input.all().map((item) => {
  const j = item.json;
  const cfg = j.config;
  const inv = j.invoice;
  const branchName = Object.fromEntries(cfg.branches.map((b) => [b.code, b.name]));
  branchName.unassigned = 'Unassigned';
  const categoryName = Object.fromEntries(cfg.categories.map((c) => [c.code, c.name]));
  const problems = problemsFor(j);
  const problemText = problems.length === 1
    ? `Problem: ${problems[0].problem}\nWhy it was flagged: ${problems[0].why}\nWhat to check: ${problems[0].check}`
    : problems.map((p, n) => `${n + 1}. Problem: ${p.problem}\n   Why it was flagged: ${p.why}\n   What to check: ${p.check}`).join('\n');

  // The QuickBooks vendor name, when one matched, so the same supplier is always spelled the same way.
  const supplierName = (j.vendor && j.vendor.name) || inv.supplier;
  const supplierForFile = cleanName(supplierName) || 'Unknown supplier';
  const numberForFile = inv.invoice_number ? inv.invoice_number.replace(/[\\/:*?"<>|\s]+/g, '-') : 'no-number_' + (inv.invoice_date || String(j.received_at).slice(0, 10));
  const invoiceFields = {
    'Invoice number': inv.invoice_number || undefined,
    'Supplier': supplierName || undefined,
    'Invoice date': inv.invoice_date || undefined,
    'Due date': inv.due_date || undefined,
    'Currency': inv.currency || undefined,
    'Subtotal': inv.subtotal ?? undefined,
    'Tax': inv.tax ?? undefined,
    'Total': inv.total ?? undefined,
    'Ship-to branch': j.allocation && j.allocation.ship_to_branch ? branchName[j.allocation.ship_to_branch] : undefined,
    'Status': j.route === 'recorded' ? 'Recorded' : 'Needs Review',
    'Review reasons': j.reasons.length ? j.reasons : undefined,
    'Problem': problems.length ? problemText : undefined,
    'Source': `${j.sender_name ? j.sender_name + ' ' : ''}<${j.sender}> · ${j.subject ? '"' + j.subject + '"' : '(no subject)'}`,
    'Received at': j.received_at,
    'Dup key': j.dup_key || undefined,
  };
  const lineFields = (inv.line_items || []).map((l, n) => ({
    'Line no': l.line_no,
    'Description': l.description,
    'Quantity': l.quantity ?? undefined,
    'Unit price': l.unit_price ?? undefined,
    'Amount': l.amount ?? undefined,
    'Branch': branchName[j.allocation.lines[n].branch] || undefined,
    'Category': categoryName[l.category] || undefined,
  }));
  return {
    json: {
      ...j,
      problems,
      problem_text: problems.length ? problemText : '',
      record: {
        drive_file_name: `${supplierForFile}_${numberForFile}.pdf`,
        invoice_fields: JSON.parse(JSON.stringify(invoiceFields)), // drops the undefined fields
        line_fields: JSON.parse(JSON.stringify(lineFields)),
      },
    },
    binary: item.binary,
  };
});

// The Airtable request for one invoice, now that the PDF is in Drive.
// typecast lets Airtable accept the select values as text (they match the field options).
const rec = $('Prepare Record').item.json;
const fileId = $json.id;
return {
  json: {
    drive_file_id: fileId,
    drive_url: fileId ? 'https://drive.google.com/file/d/' + fileId + '/view' : null,
    body: {
      typecast: true,
      records: [{
        fields: {
          ...rec.record.invoice_fields,
          'PDF': fileId ? 'https://drive.google.com/file/d/' + fileId + '/view' : undefined,
          'Execution ID': String($execution.id),
        },
      }],
    },
  },
};

// Line Items for each new Invoice record, 10 per request (Airtable's limit per call),
// each linked to its invoice. An invoice without lines sends nothing here.
const out = [];
$input.all().forEach((item, i) => {
  const created = (item.json.records || [])[0];
  const rec = $('Prepare Record').itemMatching(i).json;
  if (!created || !created.id) return;
  const lines = rec.record.line_fields || [];
  for (let start = 0; start < lines.length; start += 10) {
    out.push({
      json: {
        invoice_record_id: created.id,
        dup_key: rec.dup_key,
        lines_from: start + 1,
        lines_to: Math.min(start + 10, lines.length),
        body: {
          typecast: true,
          records: lines.slice(start, start + 10).map((f) => ({ fields: { ...f, 'Invoice': [created.id] } })),
        },
      },
    });
  }
});
return out;

// Stage 6b: find the QuickBooks vendor for each invoice that will be recorded.
// Names are compared the same way as for the duplicate key: lower case, no punctuation,
// company suffixes (LLC, Inc, Co, ...) dropped, against the vendor's display name and
// company name (accents removed: \p{M} = combining marks after NFD).
// Exactly one vendor must match. Vendors are never created here: with no
// match (or more than one), no bill is made and the invoice goes to review.
const SUFFIXES = ['llc', 'inc', 'co', 'company', 'corp', 'ltd'];
const normSupplier = (s) => String(s || '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase()
  .replace(/['’]/g, '').replace(/[^a-z0-9]+/g, ' ').trim().split(' ')
  .filter((w) => w && !SUFFIXES.includes(w)).join(' ');

const reply = $('Find QuickBooks Vendors').first().json;
const vendors = ((reply.QueryResponse && reply.QueryResponse.Vendor) || []).map((v) => ({
  id: String(v.Id),
  name: v.DisplayName,
  keys: [...new Set([v.DisplayName, v.CompanyName].filter(Boolean).map(normSupplier))],
}));

return $('To Record?').all(0).map((item) => {
  const j = item.json;
  const key = normSupplier(j.invoice && j.invoice.supplier);
  const matches = key ? vendors.filter((v) => v.keys.includes(key)) : [];
  const vendor = matches.length === 1
    ? { id: matches[0].id, name: matches[0].name, match: 'one' }
    : { id: null, name: null, match: matches.length ? 'several' : 'none', candidates: matches.map((m) => m.name) };

  if (vendor.match === 'one') {
    return { json: { ...j, vendor, vendors_checked: vendors.length }, binary: item.binary };
  }
  return {
    json: {
      ...j,
      vendor,
      vendors_checked: vendors.length,
      route: 'needs_review',
      reasons: [...j.reasons, 'vendor_not_in_quickbooks'],
      details: { ...j.details, vendor_not_in_quickbooks: { supplier: j.invoice && j.invoice.supplier, matches: matches.map((m) => m.name) } },
    },
    binary: item.binary,
  };
});

// Stage 6b: one QuickBooks bill per invoice with route "recorded" (the checks passed and
// exactly one vendor matched). Runs after the Airtable records exist, so the bill can name
// its Airtable record and the PDF. Needs-review invoices get no bill.
// One bill line per invoice line (account from the category, Class from the store),
// plus one line for the tax. The checks already made sure lines + tax = the printed total
// (within a cent per check), so the bill total matches the invoice.
const round = (n) => Math.round(Number(n) * 100) / 100;
const prepared = $('Prepare Record').all().map((p) => p.json);
const out = [];

for (const created of $('Create Invoice Record').all()) {
  const record = (created.json.records || [])[0];
  if (!record) continue;
  const dupKey = record.fields['Dup key'];
  const rec = prepared.find((p) => p.dup_key && p.dup_key === dupKey);
  if (!rec || rec.route !== 'recorded' || !rec.vendor || rec.vendor.match !== 'one') continue;

  const qb = rec.config.quickbooks;
  const inv = rec.invoice;
  const lines = inv.line_items.map((l, n) => {
    const branch = rec.allocation.lines[n].branch;
    const account = qb.accounts[l.category];
    const cls = qb.classes[branch];
    if (!account || !cls) throw new Error(`No QuickBooks account or Class for ${inv.invoice_number} line ${l.line_no} (category ${l.category}, store ${branch}). Check Config.`);
    return {
      DetailType: 'AccountBasedExpenseLineDetail',
      Amount: round(l.amount),
      Description: l.description,
      AccountBasedExpenseLineDetail: { AccountRef: { value: account }, ClassRef: { value: cls } },
    };
  });
  if (inv.tax) {
    lines.push({
      DetailType: 'AccountBasedExpenseLineDetail',
      Amount: round(inv.tax),
      Description: 'Sales tax',
      AccountBasedExpenseLineDetail: {
        AccountRef: { value: qb.tax_account },
        ClassRef: { value: qb.classes[(rec.allocation && rec.allocation.ship_to_branch) || 'shared'] },
      },
    });
  }

  const number = String(inv.invoice_number);
  const tooLong = number.length > qb.doc_number_max;
  const note = [
    `Invoice ${number} from ${rec.vendor.name}, recorded by the Copper Kettle AP automation.`,
    `Airtable record ${record.id}.`,
    record.fields.PDF ? `PDF: ${record.fields.PDF}` : null,
    `n8n execution ${$execution.id}.`,
    tooLong ? `The invoice number is longer than ${qb.doc_number_max} characters, so the bill number is shortened.` : null,
  ].filter(Boolean).join('\n');

  const body = {
    VendorRef: { value: rec.vendor.id },
    DocNumber: tooLong ? number.slice(0, qb.doc_number_max) : number,
    TxnDate: inv.invoice_date,
    PrivateNote: note,
    Line: lines,
  };
  if (inv.due_date) body.DueDate = inv.due_date;

  out.push({
    json: {
      airtable_record_id: record.id,
      dup_key: dupKey,
      invoice_number: number,
      expected_total: round(lines.reduce((sum, l) => sum + l.Amount, 0)), // what QuickBooks should show
      printed_total: round(inv.total),
      bill_url: `${qb.base_url}/bill?minorversion=${qb.minor_version}`,
      body,
    },
  });
}
return out;

// Stage 6b: write each new bill's QuickBooks ID into its Airtable invoice (10 records per
// request) and check that QuickBooks shows the total the bill was built with.
const bills = $input.all().map((item, i) => {
  const req = $('Bill Requests').itemMatching(i).json;
  const bill = item.json.Bill || {};
  const total = bill.TotalAmt === undefined ? null : Number(bill.TotalAmt);
  return {
    airtable_record_id: req.airtable_record_id,
    invoice_number: req.invoice_number,
    bill_id: bill.Id ? String(bill.Id) : null,
    bill_total: total,
    expected_total: req.expected_total,
    printed_total: req.printed_total,
    total_ok: total !== null && Math.abs(total - req.expected_total) < 0.005,
  };
});

const saved = bills.filter((b) => b.bill_id);
const out = [];
for (let start = 0; start < saved.length; start += 10) {
  const chunk = saved.slice(start, start + 10);
  out.push({
    json: {
      bills: chunk,
      body: { records: chunk.map((b) => ({ id: b.airtable_record_id, fields: { 'QuickBooks bill': b.bill_id } })) },
    },
  });
}
return out;

// Stage 6b-2: attach the invoice PDF to its new QuickBooks bill.
// QuickBooks takes files through its upload endpoint: one multipart request with two parts,
// file_metadata_01 (JSON: which bill, file name, type) and file_content_01 (the PDF).
// The metadata is sent as a small JSON file, so that part goes out as application/json.
const toBase64 = (s) => (typeof Buffer !== 'undefined' ? Buffer.from(s, 'utf8').toString('base64') : btoa(s));
const prepared = $('Prepare Record').all();
const requests = $('Bill Requests').all().map((r) => r.json);
const out = [];

$('Create Bill').all().forEach((item, i) => {
  const bill = item.json.Bill;
  const req = requests[i];
  if (!bill || !bill.Id || !req) return;
  // Create Bill answers in the order it was asked; make sure the pair really belongs together.
  if (String(bill.DocNumber) !== String(req.body.DocNumber)) {
    throw new Error(`Bill ${bill.Id} has number ${bill.DocNumber}, but request ${i + 1} was for ${req.body.DocNumber}.`);
  }
  const source = prepared.find((p) => p.json.dup_key === req.dup_key);
  if (!source || !source.binary || !source.binary.data) {
    throw new Error(`No PDF found for bill ${bill.Id} (${req.invoice_number}).`);
  }
  const qb = source.json.config.quickbooks;
  const fileName = source.json.record.drive_file_name;
  const meta = {
    AttachableRef: [{ EntityRef: { type: 'Bill', value: String(bill.Id) }, IncludeOnSend: false }],
    FileName: fileName,
    ContentType: 'application/pdf',
  };
  out.push({
    json: {
      bill_id: String(bill.Id),
      invoice_number: req.invoice_number,
      file_name: fileName,
      upload_url: `${qb.base_url}/upload?minorversion=${qb.minor_version}`,
    },
    binary: {
      meta: { data: toBase64(JSON.stringify(meta)), mimeType: 'application/json', fileName: 'metadata.json', fileExtension: 'json' },
      file: { ...source.binary.data, fileName, mimeType: 'application/pdf' },
    },
  });
});
return out;

// Stage 6b-2: did each PDF reach its bill? A failed upload does not stop the run (the bill
// and the Airtable record already exist); it is listed here so stage 7 can report it.
const results = $input.all().map((item, i) => {
  const req = $('Attachment Requests').itemMatching(i).json;
  const res = (item.json.AttachableResponse || [])[0] || {};
  const att = res.Attachable;
  const fault = res.Fault || item.json.Fault;
  const err = item.json.error;
  const ok = !!(att && att.Id);
  return {
    bill_id: req.bill_id,
    invoice_number: req.invoice_number,
    file_name: req.file_name,
    attachable_id: ok ? String(att.Id) : null,
    size: ok && att.Size !== undefined ? Number(att.Size) : null,
    ok,
    error: ok ? null : (err ? (err.message || JSON.stringify(err)) : fault ? JSON.stringify(fault) : 'No attachment in the QuickBooks reply'),
  };
});
return [{ json: { attachments: results, attached: results.filter((r) => r.ok).length, failed: results.filter((r) => !r.ok).length } }];

// Stage 7a: a short Slack note for every document that was not recorded on purpose,
// so nothing disappears silently: duplicates (with a link to the record that was kept)
// and documents that are not invoices. Errors are reported in stage 7b.
const AIRTABLE_RECORD_URL = 'https://airtable.com/YOUR_AIRTABLE_BASE_ID/YOUR_INVOICES_TABLE_ID/';
const money = (n) => (n === null || n === undefined ? 'unknown total' : '$' + Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }));
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const day = (d, zone) => {
  if (!d) return null;
  const dt = String(d).length > 10 ? DateTime.fromISO(String(d)).setZone(zone) : DateTime.fromISO(String(d));
  return dt.isValid ? dt.toFormat('LLL d, yyyy') : String(d);
};

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const zone = (j.config && j.config.timezone) || 'America/Denver';
  const from = `${j.sender_name ? j.sender_name + ' ' : ''}<${j.sender}>`;
  let text = null;

  if (j.route === 'duplicate') {
    const inv = j.invoice || {};
    const d = j.duplicate_of || {};
    const what = `${inv.supplier || 'Unknown supplier'} · ${inv.invoice_number || 'no invoice number'}`;
    const due = inv.due_date ? ` It's due ${day(inv.due_date, zone)}.` : '';
    if (d.where === 'airtable') {
      const when = d.recorded_at ? ` on ${day(d.recorded_at, zone)}` : '';
      text = `🔁 Duplicate skipped: ${esc(d.label || what)} · ${money(inv.total)} was already recorded${when} (<${AIRTABLE_RECORD_URL}${d.ref}|Airtable record>). Nothing was added.${due}`;
    } else {
      text = `🔁 Duplicate skipped: ${esc(what)} · ${money(inv.total)} is the same invoice as ${esc(d.ref || 'another file')} in this email. Only one copy was recorded.${due}`;
    }
  } else if (j.route === 'not_invoice') {
    const subject = j.subject ? `"${j.subject}"` : 'no subject';
    text = `📄 Not an invoice, skipped: ${esc(j.file_name)} from ${esc(from)} (${esc(subject)}). If it is an invoice, forward it again or add it by hand.`;
  }

  if (text) out.push({ json: { kind: j.route, file_name: j.file_name, dup_key: j.dup_key || null, text } });
}
return out;

// Stage 7a: one Slack message per invoice that needs review, sent after its Airtable record
// exists so the message can link to it. The text is the same problem statement as the
// Problem field in Airtable (Prepare Record), with a header and links. Written by code.
const AIRTABLE_RECORD_URL = 'https://airtable.com/YOUR_AIRTABLE_BASE_ID/YOUR_INVOICES_TABLE_ID/';
const money = (n) => (n === null || n === undefined ? 'unknown total' : '$' + Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }));
// Slack treats &, < and > as markup, so they are escaped in anything that came from a document or an email.
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const out = [];
$input.all().forEach((item, i) => {
  const record = (item.json.records || [])[0];
  const rec = $('Prepare Record').itemMatching(i).json;
  if (!record || rec.route !== 'needs_review') return;
  const f = rec.record.invoice_fields;
  const header = `⚠️ Needs review: ${esc(f.Supplier || 'Unknown supplier')} · ${esc(f['Invoice number'] || 'no invoice number')} · ${money(f.Total)}`;
  const links = [
    record.fields.PDF ? `<${record.fields.PDF}|PDF>` : null,
    `<${AIRTABLE_RECORD_URL}${record.id}|Airtable record>`,
  ].filter(Boolean).join(' · ');
  out.push({
    json: {
      kind: 'needs_review',
      airtable_record_id: record.id,
      file_name: rec.file_name,
      reasons: rec.reasons,
      text: [header, esc(rec.problem_text), links].join('\n'),
    },
  });
});
return out;

// Stage 7b: one row in the data table p3_processing_log for every document from the inbox.
// The same code runs in three places and recognises where it is from its input:
//   - after To Record? "false": duplicates, non-invoices and errors (nothing recorded)
//   - after Create Invoice Record: needs-review invoices (Airtable record, Drive link)
//   - after Attachment Check: recorded invoices (plus QuickBooks bill and attachment result)
// duration_ms runs from the start of reading (Read Path) to this row.
const now = Date.now();
const str = (v) => (v === null || v === undefined || v === '' ? null : String(v));
const num = (v) => (v === null || v === undefined || v === '' || !Number.isFinite(Number(v)) ? null : Number(v));

function row(j, extra) {
  const inv = j.invoice || {};
  return {
    received_at: str(j.received_at),
    mode: str(j.source),
    run_id: str(j.run_id),
    case_id: str(j.case_id),
    email_id: str(j.email_id),
    sender: str(j.sender ? `${j.sender_name ? j.sender_name + ' ' : ''}<${j.sender}>` : null),
    subject: str(j.subject),
    file_name: str(j.file_name),
    read_path: str(j.read_path),
    route: str(j.route),
    reasons: str((j.reasons || []).join(', ')),
    supplier: str((j.vendor && j.vendor.name) || inv.supplier),
    invoice_number: str(inv.invoice_number),
    total: num(inv.total),
    dup_key: str(j.dup_key),
    extracted: j.reading ? JSON.stringify(j.reading) : null,
    airtable_id: null,
    quickbooks_bill_id: null,
    drive_url: null,
    error_step: str(j.error_step),
    error_message: str(j.error_message),
    duration_ms: j.read_started_at ? now - j.read_started_at : null,
    execution_id: String($execution.id),
    ...extra,
  };
}

const items = $input.all();
const first = items.length ? items[0].json : {};
const out = [];

if (first.attachments) {
  // Recorded invoices: one Bill Requests item per bill, in the same order as Create Bill.
  const prepared = $('Prepare Record').all().map((p) => p.json);
  const bills = $('Create Bill').all().map((b) => b.json.Bill || {});
  const records = $('Create Invoice Record').all().map((c) => (c.json.records || [])[0]).filter(Boolean);
  const attachments = first.attachments;
  $('Bill Requests').all().forEach((reqItem, i) => {
    const req = reqItem.json;
    const j = prepared.find((p) => p.dup_key === req.dup_key);
    if (!j) return;
    const bill = bills[i] || {};
    const record = records.find((r) => r.id === req.airtable_record_id) || { fields: {} };
    const att = attachments.find((a) => a.bill_id === String(bill.Id)) || null;
    out.push(row(j, {
      airtable_id: req.airtable_record_id,
      quickbooks_bill_id: str(bill.Id),
      drive_url: str(record.fields.PDF),
      error_step: att && !att.ok ? 'attach_pdf' : null,
      error_message: att && !att.ok ? str(att.error) : null,
    }));
  });
} else if (first.records) {
  // Needs-review invoices, right after their Airtable record was created.
  items.forEach((item, i) => {
    const record = (item.json.records || [])[0];
    const j = $('Prepare Record').itemMatching(i).json;
    if (!record || j.route !== 'needs_review') return;
    out.push(row(j, { airtable_id: record.id, drive_url: str(record.fields.PDF) }));
  });
} else {
  // Not recorded on purpose (duplicate, not an invoice) or failed (error).
  items.forEach((item) => out.push(row(item.json, {})));
}

return out.map((json) => ({ json }));

// Stage 7b: technical problems go to #automation-errors (not #invoice-review), written by code:
// what failed, what it means, what is saved, and what to do next.
// The same code runs in two places and recognises where it is from its input:
//   - after To Record? "false": documents with route "error" (the reading failed)
//   - after Attachment Check: PDFs that did not reach their QuickBooks bill
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const short = (s, n = 300) => (String(s).length > n ? String(s).slice(0, n - 1) + '…' : String(s));
const exec = `execution ${$execution.id}`;

// What to do next after a failed reading depends on the kind of failure.
function readingNext(j) {
  const err = String(j.error_message || j.ai_error || '');
  if (j.pdf_header_ok === false) return 'Next: the file is not a real PDF (it does not start with %PDF). Ask the sender for the invoice as a PDF, then forward it again.';
  if (/unavailable|overloaded|503|timed? ?out|ECONNRESET|socket hang up/i.test(err)) return 'Next: Gemini was busy or unreachable for a moment; the invoice itself is fine. Forward the email again in a few minutes.';
  if (/too many requests|429|quota|rate limit|RESOURCE_EXHAUSTED/i.test(err)) return 'Next: the Gemini quota or rate limit was reached. Forward the email again in a few minutes; if it keeps happening, check the quota of the API key.';
  if (/authoriz|forbidden|401|403|api key|credential/i.test(err)) return 'Next: check the Gemini API key in the n8n credential, then forward the email again.';
  if (/not valid JSON|no text|not an object/i.test(err)) return 'Next: Gemini answered, but not in the expected format. Forward the email again; if it fails twice, enter the invoice by hand.';
  return 'Next: check the Gemini API key, the model name and the quota in n8n, then forward the email again.';
}

const items = $input.all();
const first = items.length ? items[0].json : {};
const out = [];

if (first.attachments) {
  for (const a of first.attachments.filter((x) => !x.ok)) {
    out.push({ json: { kind: 'attach_pdf', text: [
      `🛑 Attaching the PDF to QuickBooks bill ${esc(a.bill_id)} failed (${esc(a.invoice_number)}, ${esc(a.file_name)}).`,
      'Impact: the bill was created, but it has no PDF attached.',
      `Saved: the PDF is in the Drive folder Invoices, and the attempt is in the processing log (${exec}).`,
      'Next: attach the PDF to the bill by hand in QuickBooks. If it keeps failing, check the QuickBooks login (Sandbox environment) in n8n.',
      `Error: ${esc(short(a.error || 'unknown'))}`,
    ].join('\n') } });
  }
} else {
  for (const item of items) {
    const j = item.json;
    if (j.route !== 'error') continue;
    const from = esc(`${j.sender_name ? j.sender_name + ' ' : ''}<${j.sender}>`);
    out.push({ json: { kind: 'read', file_name: j.file_name, text: [
      `🛑 Reading the invoice failed for ${esc(j.file_name)} from ${from}.`,
      'Impact: this invoice was not recorded.',
      `Saved: the email is still in the inbox, and the attempt is in the processing log (${exec}).`,
      readingNext(j),
      `Error: ${esc(short(j.error_message || j.ai_error || 'unknown'))}`,
    ].join('\n') } });
  }
}
return out;

